## Submitted testbench
```systemverilog
`timescale 1ns / 1ps
module tb;
  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd2;

  logic        clk = 1'b0;
  logic        rst = 1'b1;
  logic        rxd = 1'b1;
  logic        m_axis_tready = 1'b1;
  logic        s_axis_tvalid = 1'b0;
  logic [7:0]  s_axis_tdata  = 8'h00;
  logic [15:0] prescale      = PRESCALE;
  wire  [7:0]  m_axis_tdata;
  wire         m_axis_tvalid;
  wire         s_axis_tready;
  wire         txd;
  wire         tx_busy, rx_busy, rx_overrun_error, rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  // 8N1 frame on rxd, LSB first, each bit prescale*8 clocks
  task automatic uart_send_byte(input logic [7:0] b);
    int bit_clks;
    bit_clks = int'(prescale) * 8;
    rxd = 1'b0;
    wait_clks(bit_clks);
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_clks(bit_clks);
    end
    rxd = 1'b1;
    wait_clks(bit_clks);
  endtask

  initial begin
    // Reset sequence
    rst = 1'b1;
    wait_clks(4);
    rst = 1'b0;
    wait_clks(4);

    // --- First word: 8'h12 ---
    uart_send_byte(8'h12);

    // Wait for first word to be delivered and accepted
    forever begin
      @(negedge clk);
      if (m_axis_tvalid && (m_axis_tdata == 8'h12)) break;
    end
    @(posedge clk); // let the delivery edge's SVA sampling complete
    // Wait for handshake to complete (tvalid drops)
    forever begin
      @(negedge clk);
      if (!m_axis_tvalid) break;
    end
    $display("First word 0x12 delivered and accepted");

    // Inter-frame gap: ensure DUT is fully idle
    wait_clks(30);

    // --- Second word: 8'h34 at prescale 2 ---
    uart_send_byte(8'h34);

    // Wait for second word delivery
    forever begin
      @(negedge clk);
      if (m_axis_tvalid && (m_axis_tdata == 8'h34)) break;
    end
    @(posedge clk); // ensure the cover property at this posedge is sampled
    wait_clks(10);

    $display("PASS R22: 0x12 then 0x34 at prescale 2, no frame error");
    $finish;
  end

  initial begin
    #10ms;
    $finish;
  end

endmodule
```

